import{j as e}from"./vendor-motion-D-QS5Tde.js";import{H as a}from"./index-DTryBJkQ.js";import{N as n,F as r}from"./Footer-KawF-dDP.js";import{P as s,C as t,N as o}from"./NextProject-BUYY37sz.js";import{C as i}from"./CsSection-D4zIf1tb.js";import{C as l}from"./CsThanks-Cx9c-DN_.js";import{B as c}from"./BottomNav-BQIsGLMm.js";import"./vendor-react-P2F7fkol.js";import"./vendor-three-CMud_36L.js";function v(){return e.jsxs(e.Fragment,{children:[e.jsxs(a,{children:[e.jsx("title",{children:"Enigma · Parth Pawar"}),e.jsx("meta",{name:"description",content:"Enigma is an interactive light sculpture that embodies a real functioning deep learning network, using 200 illuminated neurons to elucidate the complexity of neural networks."}),e.jsx("meta",{property:"og:type",content:"article"}),e.jsx("meta",{property:"og:title",content:"Enigma · Parth Pawar"}),e.jsx("meta",{property:"og:description",content:"Interactive light sculpture embodying a real functioning deep learning network."}),e.jsx("meta",{property:"og:image",content:"https://parthpawar.com/Assets/images/enigma.jpg"})]}),e.jsx(n,{}),e.jsxs("main",{id:"main-content",className:"project-main",style:{"--project-color":"#6B4C9A"},children:[e.jsx(s,{backLink:"/work",categorySlug:"ai",backLabel:"Back to Work",tags:["Creative Technology","AI","Installation"],title:"Enigma",subtitle:"Interactive light sculpture embodying a real functioning deep learning network",info:[{label:"Year",value:"2023"},{label:"Role",value:"Creator"}]}),e.jsx("section",{className:"cs-slide reveal",children:e.jsx("div",{style:{padding:"56.25% 0 0 0",position:"relative"},children:e.jsx("iframe",{src:"https://player.vimeo.com/video/895893649?h=d78737dcdb&badge=0&autopause=0&player_id=0&app_id=58479",frameBorder:"0",allow:"autoplay; fullscreen; picture-in-picture",allowFullScreen:!0,style:{position:"absolute",top:0,left:0,width:"100%",height:"100%"},title:"Enigma"})})}),e.jsx("section",{className:"cs-section reveal",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Overview"}),e.jsx("h2",{className:"cs-display",children:"200 Neurons of Light"}),e.jsxs(t,{children:[e.jsx("p",{children:"Enigma is an interactive light sculpture that intricately embodies a real functioning deep learning network, using 200 unique illuminated neurons to artistically elucidate the complexity of neural networks, inviting audiences to explore the convergence of art and science in a captivating visual experience."}),e.jsx("p",{children:"The genesis of this project drew inspiration from the ‘Abacus’ project undertaken at panGenerator Studio. While ‘the Abacus’ focused on recognizing digits, Enigma operates on a similar concept but with alphabetic characters instead of digits."})]})]})}),e.jsx(i,{id:"cs-concept",label:"01 — Concept",title:"Illuminated Neural Architecture",children:e.jsxs(t,{children:[e.jsx("p",{children:"Enigma was born from a desire to make artificial intelligence tangible. Neural networks are often described in abstract terms — layers, weights, activations — yet their inner workings remain invisible to most people. The sculpture translates that hidden computation into physical light: 200 individually addressable LED neurons are arranged in a network topology that mirrors the actual architecture of a trained neural network, turning each mathematical operation into a visible pulse of color."}),e.jsx("p",{children:"The piece takes the form of a large wall-mounted panel, roughly four feet wide and three feet tall, with each LED node suspended at a precise position corresponding to a neuron in the network’s layers. Acrylic rods and custom-fabricated mounts hold the LEDs in place, creating a three-dimensional constellation of light that reveals the structure of the model — input layer at one edge, hidden layers in the center, and output layer at the opposite edge. When the network is idle, the sculpture glows softly; when it is processing, light cascades through the layers in real time, making the flow of information something viewers can see and feel."}),e.jsx("p",{children:"Viewers are not passive observers. By writing a character on a connected tablet, they initiate inference and watch their input propagate through the physical network. The metaphor is immediate: light is information, brightness is activation strength, and the path it travels is the decision the model makes. Enigma invites audiences to develop an intuitive understanding of deep learning — not through equations or code, but through the universal language of light and motion."})]})}),e.jsx("section",{className:"cs-slide reveal",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/G1896202568057018034140303655446/1.jpg",alt:"Enigma sculpture — overview of the illuminated neural network",loading:"lazy"})}),e.jsx("section",{className:"cs-slide reveal",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/K1896202568075464778214013207062/2.jpg",alt:"Enigma sculpture — close-up of LED neurons",loading:"lazy"})}),e.jsx("section",{className:"cs-slide reveal",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/S1896202568093911522287722758678/3.jpg",alt:"Enigma sculpture — network topology detail",loading:"lazy"})}),e.jsx(i,{id:"cs-technology",label:"02 — Technology",title:"From Model to Light",children:e.jsxs(t,{children:[e.jsx("p",{children:"At the core of Enigma is a fully connected feedforward neural network trained on the EMNIST letters dataset to recognize handwritten alphabetic characters. The model consists of an input layer, two hidden layers, and an output layer — each layer physically represented by a row of LEDs on the sculpture. After training, the learned weights and biases are exported and loaded onto the hardware so the sculpture can perform inference locally, without any cloud dependency."}),e.jsx("p",{children:"The hardware stack centers on an Arduino Mega microcontroller that orchestrates the entire visualization pipeline. A companion laptop captures handwritten input from a tablet, preprocesses the image into a 28 by 28 pixel grayscale matrix, and transmits the flattened pixel values to the Arduino over serial communication. The Arduino then performs a forward pass through the network, computing activations layer by layer. Each of the 200 LEDs is driven by TLC5940 constant-current LED drivers daisy-chained together, giving individual brightness control over every node with 12-bit resolution."}),e.jsx("p",{children:"As the forward pass executes, each neuron’s activation value is mapped to an LED brightness level, so viewers see the data literally flow from the input layer through the hidden layers to the output. Highly activated neurons glow brightly while low-activation neurons remain dim, revealing which pathways the network relies on for a given character. The entire cycle — from drawing a letter to seeing the network’s prediction light up at the output layer — completes in under a second, creating a seamless real-time connection between human gesture and machine computation."})]})}),e.jsx("section",{className:"cs-slide reveal",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/E1896202568112358266361432310294/4.jpg",alt:"Enigma — technology and wiring detail",loading:"lazy"})}),e.jsx("section",{className:"cs-slide reveal",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/S1896202568130805010435141861910/5.jpg",alt:"Enigma — LED driver and Arduino setup",loading:"lazy"})}),e.jsx(i,{id:"cs-exhibition",label:"03 — Exhibition",title:"ITP Winter Show 2023",children:e.jsxs(t,{children:[e.jsx("p",{children:"Enigma was exhibited at the ITP Winter Show 2023, NYU’s flagship end-of-semester showcase where the Interactive Telecommunications Program opens its doors to the public. The show draws thousands of visitors over two days — designers, engineers, artists, families, and curious New Yorkers — making it an ideal venue to test how a broad audience engages with a piece about machine learning."}),e.jsx("p",{children:"Visitors interacted with Enigma by writing letters on a tablet stationed in front of the sculpture. As soon as a character was submitted, the network came alive: light rippled from the input layer through the hidden layers and converged on the output, where the predicted letter glowed brightest. Many visitors wrote the same letter repeatedly, noticing how different handwriting styles activated different pathways. Others tested edge cases — ambiguous letters, symbols, or scribbles — to see how the network responded to unexpected input."}),e.jsx("p",{children:"The most consistent reaction was surprise at how structured and purposeful the light patterns looked. Viewers frequently remarked that they expected AI to feel random or opaque, but watching activations cascade through defined pathways gave them an immediate sense that the network had learned real structure. Several visitors described the experience as the first time neural networks “made sense” to them. The exhibition reinforced the project’s central thesis: that making computation physically visible can bridge the gap between technical understanding and intuitive comprehension."})]})}),e.jsx("section",{className:"cs-slide reveal",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/O1896202568186145242656270516758/8.jpg",alt:"Enigma at ITP Winter Show — audience interaction",loading:"lazy"})}),e.jsx("section",{className:"cs-slide reveal",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/D1896202568204591986729980068374/9.jpg",alt:"Enigma at ITP Winter Show — exhibition view",loading:"lazy"})}),e.jsx(l,{}),e.jsx(c,{sections:[{id:"cs-concept",label:"Concept"},{id:"cs-technology",label:"Technology"},{id:"cs-exhibition",label:"Exhibition"}]})]}),e.jsx(o,{slug:"making-of-time",title:"Making of Time",image:"/Assets/images/making-of-time.jpg"}),e.jsx(r,{})]})}export{v as default};
